<template><div class="grid-wrap"><div ref="host" class="data-grid" :aria-label="title"></div></div></template>
<script setup>
import {ref,watch,onMounted,onBeforeUnmount,inject} from 'vue';
const props=defineProps({rows:Array,columns:Array,title:String,loading:Boolean,locale:String,inlineEditing:Boolean,selectable:{type:Boolean,default:true}});const emit=defineEmits(['selection','edit']);const {t,rowKey}=inject('kkdugi');const host=ref(null);let api;
onMounted(()=>{api=window.agGrid.createGrid(host.value,{theme:window.agGrid.themeQuartz.withParams({fontFamily:'Pretendard, sans-serif',fontSize:14,headerFontSize:12,headerFontWeight:500,foregroundColor:'#34454d',backgroundColor:'#ffffff',headerBackgroundColor:'#f7f9f9',borderColor:'#e6ecea',rowBorder:{color:'#eef2f0'},accentColor:'#27766a',rowHoverColor:'#f4f8f6',selectedRowBackgroundColor:'#eef7f3',wrapperBorder:false,spacing:8}),rowHeight:54,singleClickEdit:props.inlineEditing,headerHeight:43,rowData:props.rows,columnDefs:props.columns,getRowId:p=>rowKey(p.data),defaultColDef:{resizable:true,sortable:false,minWidth:100,suppressHeaderMenuButton:true},rowSelection:props.selectable?{mode:'multiRow',enableClickSelection:false,selectAll:'filtered',isRowSelectable:n=>!n.data?false:!n.data._deleted}:undefined,selectionColumnDef:{width:48,minWidth:48,maxWidth:48,pinned:'left'},getRowClass:p=>p.data?._deleted?'deleted-row':'',onSelectionChanged:()=>emit('selection',api.getSelectedRows()),onCellValueChanged:e=>emit('edit',e),stopEditingWhenCellsLoseFocus:true,localeText:{noRowsToShow:t('empty'),loadingOoo:t('loading'),selectAll:t('all'),ariaRowSelect:t('select_row'),ariaRowDeselect:t('select_row')},overlayNoRowsTemplate:'<span></span>'});});
watch(()=>props.rows,v=>{api?.setGridOption('rowData',v);api?.refreshCells({force:true});},{deep:false});watch(()=>props.columns,v=>api?.setGridOption('columnDefs',v));watch(()=>props.loading,v=>api?.setGridOption('loading',v));
defineExpose({edit:(rowIndex,colKey)=>{api?.ensureIndexVisible(rowIndex,'top');api?.ensureColumnVisible(colKey);api?.setFocusedCell(rowIndex,colKey);api?.startEditingCell({rowIndex,colKey});},stop:()=>api?.stopEditing(),clear:()=>api?.deselectAll()});onBeforeUnmount(()=>{api?.destroy();api=null;});
</script>
